package com.agentic.shortener.web;

import com.agentic.shortener.ShortenerExceptions.InvalidRequest;
import com.agentic.shortener.ShortenerProperties;
import com.agentic.shortener.service.QrCodeService;
import com.agentic.shortener.service.ShortenerService;
import io.swagger.v3.oas.annotations.Operation;
import io.swagger.v3.oas.annotations.tags.Tag;
import org.springframework.http.HttpHeaders;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

import java.nio.charset.StandardCharsets;
import java.util.Locale;

@RestController
@RequestMapping("/api/v1/urls")
@Tag(name = "QR codes")
public class QrController {

    private static final MediaType SVG = MediaType.valueOf("image/svg+xml");

    private final ShortenerService shortener;
    private final QrCodeService qr;
    private final String baseUrl;

    public QrController(ShortenerService shortener, QrCodeService qr, ShortenerProperties properties) {
        this.shortener = shortener;
        this.qr = qr;
        this.baseUrl = properties.baseUrl();
    }

    @GetMapping("/{code}/qr")
    @Operation(summary = "QR code that encodes the short URL, as PNG (default) or SVG")
    public ResponseEntity<byte[]> qr(@PathVariable String code,
                                     @RequestParam(defaultValue = "256") int size,
                                     @RequestParam(defaultValue = "png") String format) {
        if (size < QrCodeService.MIN_SIZE || size > QrCodeService.MAX_SIZE) {
            throw new InvalidRequest("size must be between " + QrCodeService.MIN_SIZE + " and " + QrCodeService.MAX_SIZE + " pixels");
        }
        String wanted = format.toLowerCase(Locale.ROOT);
        if (!wanted.equals("png") && !wanted.equals("svg")) {
            throw new InvalidRequest("format must be png or svg");
        }
        shortener.resolve(code);   // 404 for an unknown code, 410 for a deleted or expired one, exactly like the redirect
        String target = baseUrl + "/" + code;
        return wanted.equals("png")
                ? body(MediaType.IMAGE_PNG, qr.png(target, size))
                : body(SVG, qr.svg(target, size).getBytes(StandardCharsets.UTF_8));
    }

    private static ResponseEntity<byte[]> body(MediaType type, byte[] bytes) {
        return ResponseEntity.ok().contentType(type).header(HttpHeaders.CACHE_CONTROL, "max-age=300").body(bytes);
    }
}
